-- Targets schemas retailos and retailos_private ONLY. Never touches schema public (Tirumala) or the live retailos_* tables.
-- Not applied to any database yet. See docs/RETAILOS_PRODUCTION_PREFLIGHT.md before running anything.

-- M0001 foundation: schemas, shared helpers.
-- Applied on Supabase, where roles (anon, authenticated, service_role) and the auth schema
-- already exist. Nothing here creates them. No extensions are required: gen_random_uuid() and sha256()
-- are built into PostgreSQL 13+.


create schema if not exists retailos;
create schema if not exists retailos_private;
comment on schema retailos_private is
  'Helper functions and internals. NOT exposed through the Data API (keep it out of the exposed schemas list in Supabase settings).';

-- RLS policies call helpers in this schema with the caller''s privileges, so the roles need USAGE.
-- EXECUTE is granted function by function, never schema-wide.
revoke all on schema retailos_private from public;
grant usage on schema retailos_private to authenticated, service_role;
-- PostgreSQL grants EXECUTE on every new function to PUBLIC. Only a GLOBAL default-privilege change
-- (no "in schema") can remove that, so every function created from here on is closed by default
-- and opened with an explicit GRANT.
-- NOT done here (it would be project-wide and affect Tirumala): a GLOBAL "alter default privileges
-- revoke execute on functions from public". Instead every function in this design is revoked from
-- PUBLIC/anon explicitly, and tests/db/isolation.test.ts fails if one is missed.
-- Default privileges are changed only for schema retailos, for new objects created by the migration role.
alter default privileges in schema retailos revoke all on tables from anon, authenticated;
alter default privileges in schema retailos revoke all on sequences from anon, authenticated;
alter default privileges in schema retailos revoke all on functions from anon, authenticated;
grant usage on schema retailos to authenticated, service_role;

create or replace function retailos_private.set_updated_at()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

-- Raise a business error. The message is a stable code the application maps to plain language.
-- detail carries optional JSON (for example the item id) for the caller.
create or replace function retailos_private.fail(p_code text, p_detail jsonb default null)
returns void
language plpgsql
set search_path = ''
as $$
begin
  raise exception using errcode = 'P0001', message = p_code, detail = coalesce(p_detail::text, '');
end;
$$;
